/*---------------------------------------------------------------------------------------------
 *  The canonical MCP connector catalog: the single data model behind every MCP surface
 *  (sidebar marketplace pane, Settings MCP tab, and gallery-sourced entries).
 *
 *  PURE module by contract: no DI, no localize(), no platform imports. It is re-exported
 *  into the settings React bundle through settingsExternals.ts, where unresolvable imports
 *  fail only at runtime (grey screen) — nothing the compile gates can catch. Keep it that
 *  way: types, data, and pure functions only.
 *
 *  An entry's `kind` is an explicit editorial claim, never inferred from URL shape:
 *    one-click        — remote endpoint expected to complete browser OAuth unaided
 *    token-or-config  — connectable only after the user supplies inputs (token, client id)
 *    local-command    — a process on this machine; always reviewed before install
 *    skill-or-guide   — useful docs, NOT a connector; never gets a Connect button
 *    unavailable      — known broken; kept in data, filtered from the main surface
 *  `verified` is orthogonal to `kind`: it may be true only while the entry's row in
 *  docs/MCP-PROVIDER-MATRIX.md is complete (enforced by mcpProviderMatrix.test.ts).
 *--------------------------------------------------------------------------------------------*/

export type CatalogEntryKind = 'one-click' | 'token-or-config' | 'local-command' | 'skill-or-guide' | 'unavailable';
export type CatalogAuthHint = 'oauth-dcr' | 'oauth-preregistered' | 'token' | 'none';
export type CatalogTransport = 'streamable-http' | 'sse' | 'stdio';
export type CatalogCategory = 'code' | 'productivity' | 'data' | 'cloud' | 'search' | 'comms' | 'design' | 'other';

/** Mirrors the official registry server.json input shape so gallery entries map 1:1. */
export interface CatalogInput {
	readonly name: string;
	readonly target: 'env' | 'header' | 'arg';
	readonly description?: string;
	readonly isRequired?: boolean;
	readonly isSecret?: boolean;
	readonly default?: string;
	readonly choices?: readonly string[];
	readonly format?: string;
}

export interface CatalogEntry {
	/** Canonical identity; also the preferred installed-server name. */
	readonly id: string;
	/** Other configured-server names that identify this same server (exact, lowercase). */
	readonly aliases?: readonly string[];
	readonly name: string;
	readonly description: string;
	readonly kind: CatalogEntryKind;
	readonly category: CatalogCategory;
	/** Provider domain, used for the homepage link only — never for icon fetching. */
	readonly domain?: string;
	readonly transport?: CatalogTransport;
	readonly url?: string;
	readonly command?: string;
	readonly args?: readonly string[];
	/** Headers sent to a remote server; `${VAR}` values become secure prompts at install. */
	readonly headers?: Readonly<Record<string, string>>;
	/** Inputs the user must supply before connecting; orthogonal to `kind`. */
	readonly requiredInputs?: readonly CatalogInput[];
	readonly authHint?: CatalogAuthHint;
	/** PUBLIC client id of the V3Code-owned OAuth app for providers that refuse dynamic
	 *  client registration (Slack, Google Drive). Ships in the catalog on purpose: it is not
	 *  a secret (PKCE / token_endpoint_auth_method none), and it is what makes the connect
	 *  button a real one-click sign-in instead of a paste-your-own-app form. */
	readonly oauthClientId?: string;
	/** True ONLY with a complete row in docs/MCP-PROVIDER-MATRIX.md (test-enforced). */
	readonly verified?: boolean;
	/** Endpoint reported by third parties but not confirmed against first-party docs. */
	readonly unverified?: boolean;
	/** Shown inline before connecting. Warn, never block. */
	readonly caveat?: string;
	/** Docs / setup-guide target; the sole action for `skill-or-guide` entries. */
	readonly docsUrl?: string;
	/** Key into BRAND_ICON_PATHS; entries without one render a monogram tile. */
	readonly brandIcon?: string;
	/** Monogram override for the fallback tile; defaults to the first character of `name`. */
	readonly monogram?: string;
	/** `unavailable` entries only — why, kept for the detail surface. */
	readonly unavailableReason?: string;
}

