/** Inline `<svg>` markup for an entry's brand mark, or undefined → render a monogram tile. */
export function brandIconSvg(entry: Pick<CatalogEntry, 'brandIcon'>, size = 24): string | undefined {
	const d = entry.brandIcon !== undefined ? BRAND_ICON_PATHS[entry.brandIcon] : undefined;
	if (d === undefined) { return undefined; }
	return `<svg role="img" width="${size}" height="${size}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="${d}"/></svg>`;
}

export function monogramOf(entry: Pick<CatalogEntry, 'name' | 'monogram'>): string {
	return (entry.monogram ?? entry.name.charAt(0)).toUpperCase();
}

