// ============================================================================
// Identity
// ============================================================================

/**
 * Resolve a configured-server name back to its catalog entry. Exact matches only —
 * id, display name, or declared alias, compared lowercase. Never substring/slug
 * guessing: that is how one card once claimed another entry's server.
 */
export function catalogEntryForServerName(serverName: string, catalog: readonly CatalogEntry[] = CATALOG): CatalogEntry | undefined {
	const needle = serverName.toLowerCase();
	return catalog.find(e =>
		e.id.toLowerCase() === needle
		|| e.name.toLowerCase() === needle
		|| (e.aliases ?? []).some(a => a.toLowerCase() === needle)
	);
}

/** True when the entry represents a remote (HTTP/SSE) server. */
export function isRemoteEntry(entry: Pick<CatalogEntry, 'kind' | 'url'>): boolean {
	return (entry.kind === 'one-click' || entry.kind === 'token-or-config') && entry.url !== undefined;
}

// ============================================================================
// Unresolved-variable detection (the ONE detector — never duplicate this regex)
// ============================================================================

const VARIABLE_RE = /\$\{([^}]+)\}/g;

/**
 * `${...}` forms the editor itself resolves; anything else is an unresolved placeholder.
 * Exact-match by design: prefixed kinds require the ':' (so `${environment}` is NOT
 * mistaken for `${env:...}`), and bare names must match whole (`${workspaceFolder}` and
 * the scoped `${workspaceFolder:name}` pass; `${workspaceFolderX}` does not).
 */
const RESOLVABLE_VARIABLE_RE = /^(?:input|env|config|command):|^(?:workspaceFolder(?::.+)?|workspaceFolderBasename|userHome|pathSeparator|cwd)$/;

/**
 * Every bare `${VAR}` in the given strings that the editor will NOT resolve before
 * connecting. A non-empty result means the value must never reach the network as-is —
 * this is exactly how `Bearer ${GITHUB_PERSONAL_ACCESS_TOKEN}` once went over the wire.
 */
export function findUnresolvedVariables(values: Iterable<string | undefined>): string[] {
	const found = new Set<string>();
	for (const value of values) {
		if (value === undefined) { continue; }
		for (const match of value.matchAll(VARIABLE_RE)) {
			const name = match[1];
			if (!RESOLVABLE_VARIABLE_RE.test(name)) {
				found.add(name);
			}
		}
	}
	return [...found].sort();
}

/**
 * All strings of a config entry that can carry placeholders, for findUnresolvedVariables.
 * KEYS are included too: upstream's expression parser walks object keys, so a templated
 * header or env NAME is launch-refused just like a templated value.
 */
export function configEntryStrings(entry: { url?: string | { toString(): string }; headers?: Record<string, string>; command?: string; args?: readonly string[]; env?: Record<string, string> }): string[] {
	return [
		entry.url?.toString(),
		...Object.keys(entry.headers ?? {}),
		...Object.values(entry.headers ?? {}),
		entry.command,
		...(entry.args ?? []),
		...Object.keys(entry.env ?? {}),
		...Object.values(entry.env ?? {}),
	].filter((s): s is string => s !== undefined);
}

/**
 * The install payload for a catalog entry, identical across every surface. Required
 * inputs that the config does not already carry are synthesized as bare placeholders
 * so the normalization pipeline turns them into secure prompts — values are typed by
 * the user at connect time, never baked into the catalog or the config.
 */
export function installEntryForCatalogEntry(entry: CatalogEntry): { url?: string; headers?: Record<string, string>; oauth?: { clientId?: string }; command?: string; args?: string[]; env?: Record<string, string> } | undefined {
	if (entry.kind === 'skill-or-guide' || entry.kind === 'unavailable') {
		return undefined;
	}

	const headers: Record<string, string> = { ...(entry.headers ?? {}) };
	const env: Record<string, string> = {};
	const headerValues = Object.values(headers);
	for (const input of entry.requiredInputs ?? []) {
		if (input.target === 'header') {
			// Only synthesize when no declared header already carries this placeholder —
			// GitHub-style entries declare `Authorization: Bearer \${PAT}` themselves.
			if (!headerValues.some(v => v.includes(`\${${input.name}}`)) && headers[input.name] === undefined) {
				headers[input.name] = `\${${input.name}}`;
			}
		} else if (input.target === 'env') {
			env[input.name] = `\${${input.name}}`;
		}
	}

	if (entry.url !== undefined) {
		return {
			url: entry.url,
			headers: Object.keys(headers).length > 0 ? headers : undefined,
			...(entry.oauthClientId ? { oauth: { clientId: entry.oauthClientId } } : {}),
		};
	}
	if (entry.command !== undefined) {
		// ${workspaceFolder} stays symbolic: upstream-managed installs carry
		// variableReplacement and resolve it per-window at launch — baking today's
		// absolute path into a user-scope config would silently point the server at a
		// stale workspace forever.
		return { command: entry.command, args: [...(entry.args ?? [])], env: Object.keys(env).length > 0 ? env : undefined };
	}
	return undefined;
}

// ============================================================================
// Actions
// ============================================================================

export type CatalogPrimaryAction = 'connect' | 'set-up' | 'review-command' | 'open-guide' | null;

/** The single primary action an UNCONFIGURED entry offers. Configured servers use recoveryActionFor. */
export function primaryActionFor(entry: Pick<CatalogEntry, 'kind'>): CatalogPrimaryAction {
	switch (entry.kind) {
		case 'one-click': return 'connect';
		case 'token-or-config': return 'set-up';
		case 'local-command': return 'review-command';
		case 'skill-or-guide': return 'open-guide';
		case 'unavailable': return null;
	}
}

export type CatalogRecoveryAction = 'sign-in' | 'reconnect' | 'sign-in-again' | null;

/**
 * Which recovery button a CONFIGURED server's card shows, matching the repaired flows:
 *  - needs-user-interaction → 'sign-in' (browser OAuth is waiting on the user)
 *  - remote, healthy (connected with tools) → 'sign-in-again' (full fresh auth)
 *  - remote, anything else → 'reconnect' (cheap stop/start)
 *  - local commands → none (toggle and Disconnect only)
 * Truthfulness invariant: "healthy" for remotes means status success AND at least one tool.
 */
export function recoveryActionFor(
	entry: Pick<CatalogEntry, 'kind' | 'url'>,
	server: { status: string; tools?: readonly unknown[] } | undefined,
	isOn: boolean,
): CatalogRecoveryAction {
	if (server?.status === 'needs-user-interaction') { return 'sign-in'; }
	if (!isRemoteEntry(entry)) { return null; }
	const toolCount = server?.tools?.length ?? 0;
	return server?.status === 'success' && isOn && toolCount > 0 ? 'sign-in-again' : 'reconnect';
}

// ============================================================================
// Error text
// ============================================================================

/**
 * Transport failures arrive as raw exception text ("Error POSTing to endpoint (HTTP
 * 401)...", "spawn npx ENOENT"). Cards show a sentence a person can act on, and keep
 * the original as a tooltip so nothing is lost.
 */
export function humanizeError(raw: string, entry?: Pick<CatalogEntry, 'command'>): string {
	const e = raw.toLowerCase();
	if (e.includes('401') || e.includes('unauthorized') || e.includes('invalid_token')) {
		return 'This service needs you to sign in before it will answer.';
	}
	if (e.includes('invalid_client')) {
		return 'The service did not recognize this editor as a registered app. It may need a pre-registered client ID.';
	}
	if (e.includes('invalid_redirect')) {
		return 'The service rejected the sign-in return address. Wait a few seconds and try signing in again.';
	}
	if (e.includes('403') || e.includes('forbidden')) {
		return 'Signed in, but this account is not allowed to use this server.';
	}
	if (e.includes('enoent') || e.includes('not recognized') || e.includes('command not found')) {
		return entry?.command !== undefined
			? `"${entry.command}" was not found on your PATH — install it, then reconnect.`
			: 'The server command was not found on your PATH.';
	}
	if (e.includes('econnrefused') || e.includes('enotfound') || e.includes('fetch failed') || e.includes('network')) {
		return 'Could not reach the server. Check your connection or proxy and try again.';
	}
	if (e.includes('timed out') || e.includes('etimedout')) {
		return 'The server took too long to respond.';
	}
	if (e.includes('404')) {
		return 'The server endpoint returned Not Found — the URL may have moved.';
	}
	if (e.includes('unresolved placeholder')) {
		return 'The server config still contains placeholder values. Open the config and fill them in.';
	}
	const firstLine = raw.split('\n')[0].trim();
	return firstLine.length > 160 ? `${firstLine.slice(0, 157)}…` : firstLine;
}

// ============================================================================
// Gallery (official MCP registry) mapping
// ============================================================================

/**
 * Structural mirrors of the upstream gallery types (platform/mcp/common/mcpManagement.ts).
 * Structural on purpose: platform const enums cannot cross the settings-bundle boundary.
 */
export interface GalleryKeyValueInputLike {
	readonly name: string;
	readonly value?: string;
	readonly description?: string;
	readonly isRequired?: boolean;
	readonly isSecret?: boolean;
	readonly default?: string;
	readonly choices?: readonly string[];
}

export interface GalleryRemoteLike {
	readonly type: string; // 'streamable-http' | 'sse'
	readonly url: string;
	readonly headers?: readonly GalleryKeyValueInputLike[];
}

export interface GalleryPackageLike {
	readonly registryType: string; // 'npm' | 'pypi' | 'oci' | 'nuget' | 'mcpb' | ...
	readonly identifier: string;
	readonly version?: string;
	readonly runtimeHint?: string;
	readonly environmentVariables?: readonly GalleryKeyValueInputLike[];
}

export interface GalleryServerLike {
	readonly name: string;
	readonly displayName: string;
	readonly description: string;
	readonly status: string; // 'active' | 'deprecated'
	readonly webUrl?: string;
	readonly repositoryUrl?: string;
	readonly icon?: { readonly dark: string; readonly light: string };
	readonly configuration: {
		readonly packages?: readonly GalleryPackageLike[];
		readonly remotes?: readonly GalleryRemoteLike[];
	};
}

function galleryInputsToCatalogInputs(inputs: readonly GalleryKeyValueInputLike[] | undefined, target: CatalogInput['target']): CatalogInput[] {
	return (inputs ?? []).map(i => ({
		name: i.name,
		target,
		description: i.description,
		isRequired: i.isRequired,
		isSecret: i.isSecret,
		default: i.default,
		choices: i.choices,
	}));
}

/** A registry remote URL with `{var}` or `${var}` templating cannot be connected verbatim. */
function isTemplatedUrl(url: string): boolean {
	return /[{]/.test(url);
}

const LOCAL_COMMAND_OF_REGISTRY_TYPE: Record<string, (p: GalleryPackageLike) => { command: string; args: string[] }> = {
	'npm': p => ({ command: p.runtimeHint ?? 'npx', args: ['-y', p.version !== undefined ? `${p.identifier}@${p.version}` : p.identifier] }),
	'pypi': p => ({ command: p.runtimeHint ?? 'uvx', args: [p.version !== undefined ? `${p.identifier}==${p.version}` : p.identifier] }),
	'oci': p => ({ command: p.runtimeHint ?? 'docker', args: ['run', '-i', '--rm', p.identifier] }),
};

/**
 * The five-state classification for a gallery server, per the mapping table in the
 * rebuild plan. `authHint` is NEVER derived here: the registry does not declare auth,
 * OAuth support is discovered at runtime per the MCP spec.
 */
export function classifyGalleryServer(g: GalleryServerLike): CatalogEntryKind {
	const hasDocs = g.webUrl !== undefined || g.repositoryUrl !== undefined;
	if (g.status === 'deprecated') {
		return hasDocs ? 'skill-or-guide' : 'unavailable';
	}
	const remotes = g.configuration.remotes ?? [];
	if (remotes.length > 0) {
		const remote = remotes[0];
		const needsInput = (remote.headers ?? []).some(h => h.isSecret === true || h.isRequired === true) || isTemplatedUrl(remote.url);
		return needsInput ? 'token-or-config' : 'one-click';
	}
	const packages = g.configuration.packages ?? [];
	if (packages.length > 0) {
		return packages.some(p => LOCAL_COMMAND_OF_REGISTRY_TYPE[p.registryType] !== undefined) ? 'local-command' : 'skill-or-guide';
	}
	return hasDocs ? 'skill-or-guide' : 'unavailable';
}

/** Map one gallery server onto the canonical entry model. Never `verified`; no `authHint`. */
export function galleryServerToCatalogEntry(g: GalleryServerLike): CatalogEntry {
	const kind = classifyGalleryServer(g);
	const remote = (g.configuration.remotes ?? [])[0];
	const pkg = (g.configuration.packages ?? []).find(p => LOCAL_COMMAND_OF_REGISTRY_TYPE[p.registryType] !== undefined);

	const base = {
		id: g.name,
		name: g.displayName || g.name,
		description: g.description,
		kind,
		category: 'other' as const,
		docsUrl: g.webUrl ?? g.repositoryUrl,
	};

	if ((kind === 'one-click' || kind === 'token-or-config') && remote !== undefined) {
		return {
			...base,
			transport: remote.type === 'sse' ? 'sse' : 'streamable-http',
			url: remote.url,
			requiredInputs: galleryInputsToCatalogInputs(remote.headers, 'header'),
		};
	}
	if (kind === 'local-command' && pkg !== undefined) {
		const { command, args } = LOCAL_COMMAND_OF_REGISTRY_TYPE[pkg.registryType](pkg);
		return {
			...base,
			transport: 'stdio',
			command,
			args,
			requiredInputs: galleryInputsToCatalogInputs(pkg.environmentVariables, 'env'),
		};
	}
	return kind === 'unavailable' ? { ...base, unavailableReason: 'The registry entry has no installable configuration.' } : base;
}
